UPDATE mk_runtime_slot
SET desired_generation = #{desiredGeneration},
    activation_sequence = #{activationSequence},
    directive_signature = #{directiveSignature},
    directive_json = #{directiveJson},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND environment_name = #{environmentName}
  AND cell_id = #{cellId}
