mapper.select:
SELECT
    tenant_id AS tenantId,
    desired_generation AS desiredGeneration,
    activation_sequence AS activationSequence
FROM mk_runtime_slot
WHERE environment_name = #{environmentName}
  AND cell_id = #{cellId}
  AND runtime_name = 'decision'
  AND namespace_name = #{namespaceName}
  AND desired_generation > 0

SELECT
    release_key_id AS releaseKeyId,
    manifest_json AS manifestJson,
    artifact_payload AS artifactPayload
FROM mk_runtime_generation
WHERE tenant_id = #{tenantId}
  AND environment_name = #{environmentName}
  AND cell_id = #{cellId}
  AND runtime_name = 'decision'
  AND namespace_name = #{namespaceName}
  AND generation_no = #{generationNo}

