UPDATE mk_audience_membership_projection
SET member_value = #{memberValue},
    membership_version = #{membershipVersion},
    expires_at = #{expiresAt},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND audience_id = #{audienceId}
  AND subject_hash = #{subjectHash}
  AND membership_version < #{membershipVersion}

UPDATE mk_decision_kill_switch
SET switch_sequence = #{switchSequence},
    enabled_value = #{enabledValue},
    reason_text = #{reasonText},
    directive_signature = #{directiveSignature},
    directive_json = #{directiveJson},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND namespace_name = #{namespaceName}
